from math import gcd
from math import comb

def check_n(n):
    solutions_for_n = []

    import math
    a_min = math.floor(n / 3) + 1
    a_max = math.ceil(n / 2) - 1

    if a_min > a_max:
        # No valid 'a' exists for this n
        return (n, False, [], [])

    n_is_solution = True
    r1_cases = [] 
    r_greater_than_1_cases = [] 

    for a in range(a_min, a_max + 1):
        r = n - 2 * a

        try:
            C_val = comb(a - 1, r - 1)
        except ValueError:
            C_val = 0 

        is_divisible = (C_val % r == 0)

        if not is_divisible:
            n_is_solution = False
            break 
        else:
            config = (n, a, r, C_val)
            solutions_for_n.append(config)

            if r == 1:
                r1_cases.append((n, a, r))
            else:
                r_greater_than_1_cases.append((n, a, r))

    return (n, n_is_solution, solutions_for_n, (r1_cases, r_greater_than_1_cases))

