import math

def check_condition(n, a):
    """Checks if C(a-1, n-2a-1) is a multiple of n-2a for given n and a."""
    r = n - 2 * a
    if r <= 0:
        # Should not happen given the range of a, but safety check
        return False

    # Binomial coefficient is C(a-1, r-1)
    k = r - 1
    N = a - 1
    K = r - 1

    if K < 0 or K > N:
        # Binomial coefficient is 0, which is divisible by any r >= 1
        return True 

    try:
        C = math.comb(N, K)
    except ValueError:
        # Should not happen if logic is correct, but handles large inputs/errors
        return False 

    return C % r == 0

def verify_n(n):
    """Verifies if n is a solution by checking all valid 'a'."""
    if n % 2 == 0 or n % 3 == 0 or n <= 1:
        return False

    # Valid range for a: n/3 < a < n/2
    a_min = math.floor(n / 3) + 1
    a_max = math.ceil(n / 2) - 1

    if a_min > a_max:
        # No valid a exists
        return False

    is_solution = True
    for a in range(a_min, a_max + 1):
        if not check_condition(n, a):
            # Found a counterexample 'a' for this 'n'
            return False

    return True

